messages.content:
Exercise: Flower Field (flower-field)
Difficulty: 6/9

Instructions:
# Instructions

Your task is to add flower counts to empty squares in a completed Flower Field garden.
The garden itself is a rectangle board composed of squares that are either empty (`' '`) or a flower (`'*'`).

For each empty square, count the number of flowers adjacent to it (horizontally, vertically, diagonally).
If the empty square has no adjacent flowers, leave it empty.
Otherwise replace it with the count of adjacent flowers.

For example, you may receive a 5 x 4 board like this (empty spaces are represented here with the '·' character for display on screen):

```text
·*·*·
··*··
··*··
·····
```

Which your code should transform into this:

```text
1*3*1
13*31
·2*2·
·111·
```


Starter file:
```zig
const std = @import("std");
const mem = std.mem;

pub fn annotate(allocator: mem.Allocator, garden: []const []const u8) mem.Allocator.Error![][]u8 {
    _ = allocator;
    _ = garden;
    @compileError("please implement the annotate function");
}

```

Tests that will be run with `zig test`:
```zig
const std = @import("std");
const testing = std.testing;

const annotate = @import("flower_field.zig").annotate;

fn free(slices: [][]u8) void {
    for (slices) |slice| {
        testing.allocator.free(slice);
    }
    testing.allocator.free(slices);
}

fn annotateTest(allocator: std.mem.Allocator, expected: []const []const u8, garden: []const []const u8) !void {
    const actual = try annotate(allocator, garden);
    defer free(actual);
    try testing.expectEqual(expected.len, actual.len);
    for (0..expected.len) |i| {
        try testing.expectEqualStrings(expected[i], actual[i]);
    }
}

test "no rows" {
    const garden = [_][]const u8{};
    const expected = [_][]const u8{};
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "no columns" {
    const garden = [_][]const u8{
        "", //
    };
    const expected = [_][]const u8{
        "", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "no flowers" {
    const garden = [_][]const u8{
        "   ", //
        "   ", //
        "   ", //
    };
    const expected = [_][]const u8{
        "   ", //
        "   ", //
        "   ", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "garden full of flowers" {
    const garden = [_][]const u8{
        "***", //
        "***", //
        "***", //
    };
    const expected = [_][]const u8{
        "***", //
        "***", //
        "***", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "flower surrounded by spaces" {
    const garden = [_][]const u8{
        "   ", //
        " * ", //
        "   ", //
    };
    const expected = [_][]const u8{
        "111", //
        "1*1", //
        "111", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "space surrounded by flowers" {
    const garden = [_][]const u8{
        "***", //
        "* *", //
        "***", //
    };
    const expected = [_][]const u8{
        "***", //
        "*8*", //
        "***", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "horizontal line" {
    const garden = [_][]const u8{
        " * * ", //
    };
    const expected = [_][]const u8{
        "1*2*1", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "horizontal line, flowers at edges" {
    const garden = [_][]const u8{
        "*   *", //
    };
    const expected = [_][]const u8{
        "*1 1*", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "vertical line" {
    const garden = [_][]const u8{
        " ", //
        "*", //
        " ", //
        "*", //
        " ", //
    };
    const expected = [_][]const u8{
        "1", //
        "*", //
        "2", //
        "*", //
        "1", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "vertical line, flowers at edges" {
    const garden = [_][]const u8{
        "*", //
        " ", //
        " ", //
        " ", //
        "*", //
    };
    const expected = [_][]const u8{
        "*", //
        "1", //
        " ", //
        "1", //
        "*", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "cross" {
    const garden = [_][]const u8{
        "  *  ", //
        "  *  ", //
        "*****", //
        "  *  ", //
        "  *  ", //
    };
    const expected = [_][]const u8{
        " 2*2 ", //
        "25*52", //
        "*****", //
        "25*52", //
        " 2*2 ", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "large garden" {
    const garden = [_][]const u8{
        " *  * ", //
        "  *   ", //
        "    * ", //
        "   * *", //
        " *  * ", //
        "      ", //
    };
    const expected = [_][]const u8{
        "1*22*1", //
        "12*322", //
        " 123*2", //
        "112*4*", //
        "1*22*2", //
        "111111", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

test "multiple adjacent flowers" {
    const garden = [_][]const u8{
        " ** ", //
    };
    const expected = [_][]const u8{
        "1**1", //
    };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        annotateTest,
        .{ &expected, &garden },
    );
}

```

